use serde::{Deserialize, Serialize};
use std::collections::HashMap;
#[doc = " Copies extracted declarations to the specified output directory."]
pub fn copy_declarations_to_output(
    crate_name: &str,
    declarations: &HashMap<String, String>,
    output_base_path: &Path,
) -> Result<()> {
    let crate_output_dir = output_base_path.join(crate_name).join("src").join("decls");
    std::fs::create_dir_all(&crate_output_dir).context(format!(
        "Failed to create output directory for declarations: {}",
        crate_output_dir.display()
    ))?;
    for (decl_name, decl_tokens_str) in declarations {
        let file_path = crate_output_dir.join(format!("{}.rs", decl_name));
        std::fs::write(&file_path, decl_tokens_str).context(format!(
            "Failed to write declaration to {}",
            file_path.display()
        ))?;
    }
    Ok(())
}
